<div class="page-heading"><h1>Pusat Belajar</h1><p>Pelajari materi, kumpulkan tugas, dan siapkan sesi praktik Anda.</p></div>
<?php $batchId=(int)query('batch');if(!$batchId): ?>
<?php if(!$enrollments)emptyState('Ruang belajar Anda masih kosong','Akses materi tersedia setelah pendaftaran disetujui.','portal.php?view=registrations','Lihat pendaftaran'); ?>
<div class="portal-grid"><?php foreach($enrollments as $en): ?><a class="panel" href="portal.php?view=learning&amp;batch=<?= (int)$en['batch_id'] ?>"><h2><?= e($en['title']) ?></h2><p class="muted"><?= e($en['delivery_format']) ?></p><div class="actions"><span class="btn">Buka materi</span></div></a><?php endforeach; ?></div>
<?php else: authorizedBatch($uid,$batchId);$batch=one('SELECT b.*,p.title,s.equipment,s.practical_info FROM training_batches b JOIN training_programs p ON p.slug=b.program_slug LEFT JOIN batch_settings s ON s.batch_id=b.id WHERE b.id=?',[$batchId]);$pr=progress($uid,$batchId); ?>
<section class="panel"><div class="row"><h2><?= e($batch['title']) ?></h2><a href="portal.php?view=learning" class="btn secondary">Semua kelas</a></div><p class="muted"><?= e($batch['location']?:'Lokasi mengikuti informasi sesi') ?> · <?= e($batch['delivery_format']) ?></p><div class="progress-track"><span style="width:<?= $pr['percent'] ?>%"></span></div><div class="row muted"><span>Materi <?= (int)$pr['lessons']['done'] ?>/<?= (int)$pr['lessons']['total'] ?></span><span>Tugas lulus <?= (int)$pr['assignments']['done'] ?>/<?= (int)$pr['assignments']['total'] ?></span><span>Kehadiran <?= (int)$pr['attendance']['done'] ?>/<?= (int)$pr['attendance']['total'] ?></span></div><?php if($batch['practical_info']||$batch['equipment']): ?><h3 style="margin-top:20px">Persiapan praktik</h3><p class="lesson-body"><?= e($batch['practical_info']) ?></p><p class="lesson-body"><?= e($batch['equipment']) ?></p><?php endif; ?></section>
<?php $lessons=rows('SELECT l.*,c.completed_at FROM lessons l LEFT JOIN lesson_completions c ON c.lesson_id=l.id AND c.user_id=? WHERE l.batch_id=? AND l.is_published=1 ORDER BY l.sort_order,l.id',[$uid,$batchId]); ?>
<div class="stack" style="margin-top:24px"><?php if(!$lessons)emptyState('Materi belum dipublikasikan','Admin akan mengumumkan materi yang siap dipelajari.','portal.php?view=schedule','Lihat jadwal kelas'); ?>
<?php foreach($lessons as $lesson): ?><details class="panel" <?= (int)query('lesson')===(int)$lesson['id']?'open':'' ?>><summary><span class="badge"><?= e($lesson['module_title']) ?></span><h3><?= e($lesson['title']) ?> <?= $lesson['completed_at']?'✓':'' ?></h3></summary><div class="lesson-body"><?= e($lesson['body']) ?></div><?php if($lesson['kind']==='video' && $lesson['file_path'] && strtolower(pathinfo($lesson['file_path'],PATHINFO_EXTENSION))==='mp4'): ?><video class="private-media" controls preload="metadata" src="download.php?kind=lesson&amp;id=<?= (int)$lesson['id'] ?>&amp;inline=1">Browser Anda belum mendukung video ini.</video><?php endif; ?><?php if($url=safeUrl($lesson['video_url'])): ?><div class="actions"><a class="btn secondary" target="_blank" rel="noopener noreferrer" href="<?= e($url) ?>">Tonton video pembelajaran</a></div><?php endif; ?><?php if($lesson['file_path']): ?><div class="actions"><a class="btn secondary" href="download.php?kind=lesson&amp;id=<?= (int)$lesson['id'] ?>">Unduh <?= e($lesson['file_name']?:'materi') ?></a></div><?php endif; ?><?php if(!$lesson['completed_at']): ?><form method="post" class="portal-form" style="margin-top:20px" data-consent-form data-busy-form><?= actionFields('complete_lesson',(int)$lesson['id']) ?><label class="check"><input type="checkbox" name="completed" value="1" required>Saya sudah mempelajari materi ini.</label><button type="submit" class="btn" disabled>Tandai materi selesai</button></form><?php else: ?><p class="notice">Ditandai selesai pada <?= e($lesson['completed_at']) ?>.</p><?php endif; ?></details><?php endforeach; ?></div>
<?php $assignments=rows('SELECT a.*,s.answer,s.file_path,s.id submission_id,s.status,s.feedback FROM assignments a LEFT JOIN assignment_submissions s ON s.assignment_id=a.id AND s.user_id=? WHERE a.batch_id=? AND a.is_published=1 ORDER BY a.due_at,a.id',[$uid,$batchId]); ?>
<?php if($assignments): ?><h2 style="font-size:24px;font-weight:800;margin:30px 0 18px">Tugas dan praktik</h2><div class="stack"><?php foreach($assignments as $assignment): ?><section class="panel"><div class="row"><h2><?= e($assignment['title']) ?></h2><span class="badge"><?= e($assignment['status']?statusText($assignment['status']):'Belum dikumpulkan') ?></span></div><p class="lesson-body"><?= e($assignment['instructions']) ?></p><p class="muted">Batas pengumpulan: <?= e($assignment['due_at']?:'Belum ditetapkan') ?></p><?php if($assignment['feedback']): ?><p class="notice info"><?= e($assignment['feedback']) ?></p><?php endif; ?><?php if($assignment['file_path']): ?><a href="download.php?kind=submission&amp;id=<?= (int)$assignment['submission_id'] ?>">Unduh kiriman Anda</a><?php endif; ?><?php if($assignment['status']!=='passed'&&(!$assignment['due_at']||strtotime($assignment['due_at'])>=time())): ?><form class="portal-form" method="post" enctype="multipart/form-data" style="margin-top:20px" data-busy-form><?= actionFields('assignment',(int)$assignment['id']) ?><label>Jawaban<textarea name="answer" maxlength="20000"><?= e($assignment['answer']) ?></textarea></label><label>Dokumen tugas (PDF, maksimal 2 MB)<input type="file" name="document" accept="application/pdf"></label><button class="btn" type="submit">Kumpulkan tugas</button></form><?php endif; ?></section><?php endforeach; ?></div><?php endif; ?>
<?php endif; ?>
